llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug, had only 15% oral bioavailability in humans, demonstrating that esterification with a lipophilic chain does not guarantee F >= 20%; orlistat's reactive beta-lactone and extreme lipophilicity are expected to be even less favorable for systemic absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a dodecyl ester of a dipeptide, showed average 60% oral bioavailability in healthy volunteers; this superficially supports high F for a dodecyl ester, but DVAS lacks the reactive beta-lactone and is a more soluble peptide prodrug, so transferability to orlistat is low.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain fatty ester prodrug, had absolute oral bioavailability of 85 ± 15% in children; this supports high F for lipophilic esters, but it is a prodrug of a smaller, absorbable drug rather than a locally acting beta-lactone lipase inhibitor.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Perindopril, an ester prodrug, had 66% absolute oral bioavailability in humans; this supports high F for ester-containing drugs, but perindopril is a small ACE inhibitor with better aqueous solubility, not a highly lipophilic beta-lactone.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a beta-lactone pancreatic lipase inhibitor designed to act locally in the GI tract. Its systemic oral bioavailability is negligible (<2%), far below 20%. The high-F long-chain ester analogs are prodrugs of more polar drugs and do not transfer; the only low-F ester prodrug record (laninamivir octanoate, 15%) is directionally consistent. Predict low.",
  "evidence_gaps": [
    "No direct orlistat bioavailability record is present in the provided evidence set.",
    "No close structural analog with a beta-lactone and long alkyl chains was provided; the low-F record is a polar ester prodrug."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

